contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address logAddr) public {
        bool reverted;
        c.SetLogFile(logAddr); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        bool initializedBefore = false; // cannot read intitalized directly; infer via the call only
        // The rule: SetLogFile succeeds only if not initialized. Since we only run once and
        // nothing initialized before, it must succeed. On success the stored address must equal logAddr.
        assert(!reverted);
    }

    receive() external payable {}
}

